<script setup>
import { computed, onMounted, ref } from 'vue'
import { getFinanceTaxDraft, saveFinanceTaxDraft, getFinanceReportingHistory } from '@/services/finance'
import { companyProfile } from '@/services/company'
import { makeCoretaxDraft, validateCoretaxDraft, downloadCoretaxXML } from '@/utils/coretaxDraft'
import { reportMoney as money } from '@/utils/financeReporting'
import { financeError, financeDate } from '@/composables/useFinanceLedger'
import { downloadFinanceXlsx, openFinancePrint, writeFinancePrint } from '@/utils/financeDocuments'
import { useModalDialog } from '@/composables/useModalDialog'
import FasSelect from '@/components/ui/FasSelect.vue'
const props=defineProps({invoiceId:{type:String,required:true}}),emit=defineEmits(['close','saved'])
const source=ref(null),document=ref(null),fingerprint=ref(''),revision=ref(0),saved=ref(''),savedFingerprint=ref(''),busy=ref(false),loading=ref(true),error=ref(''),message=ref(''),history=ref([])
const columns=[['code','Kode barang DJP'],['unit','Kode satuan DJP'],['price','Harga sebelum PPN'],['discount','Total diskon'],['base','TaxBase'],['other_base','OtherTaxBase / DPP PPN'],['vat_rate','Tarif PPN (%)'],['vat','PPN']]
const dirty=computed(()=>JSON.stringify(document.value)!==saved.value),stale=computed(()=>revision.value>0&&savedFingerprint.value!==fingerprint.value)
const checks=computed(()=>source.value&&document.value?validateCoretaxDraft(document.value,source.value):[])
const close=()=>{if(!busy.value)emit('close')}
useModalDialog(()=>source.value||loading.value?'#tax-draft-dialog':'',close)
const load=async()=>{loading.value=true;error.value='';try{const r=await getFinanceTaxDraft(props.invoiceId);source.value=r.source;fingerprint.value=r.fingerprint;revision.value=r.draft.revision;savedFingerprint.value=r.draft.source_fingerprint||'';document.value=r.draft.document||makeCoretaxDraft(r.source,companyProfile);saved.value=JSON.stringify(document.value)}catch(e){error.value=financeError(e)}finally{loading.value=false}}
const save=async()=>{if(busy.value||!document.value)return;busy.value=true;error.value='';try{const r=await saveFinanceTaxDraft(props.invoiceId,{document:document.value,revision:revision.value,fingerprint:fingerprint.value});revision.value=r.draft.revision;savedFingerprint.value=r.draft.source_fingerprint;saved.value=JSON.stringify(document.value);message.value='Draft tersimpan. Belum dikirim, ditandatangani, atau disahkan DJP.';emit('saved')}catch(e){error.value=financeError(e)}finally{busy.value=false}}
const exportXML=async()=>{busy.value=true;error.value='';try{const fresh=await getFinanceTaxDraft(props.invoiceId);if(fresh.fingerprint!==fingerprint.value||fresh.draft.revision!==revision.value)throw new Error('Faktur atau draft berubah. Tutup lalu buka kembali sebelum ekspor.');downloadCoretaxXML(document.value,source.value)}catch(e){error.value=financeError(e)}finally{busy.value=false}}
const rows=computed(()=>document.value?.items.map(item=>[source.value.invoice_number,item.name,item.qty,item.code,item.unit,item.price,item.discount,item.base,item.other_base,item.vat_rate,item.vat])||[])
const exportReview=kind=>{try{const headings=['Faktur','Produk','Qty','Kode','Satuan DJP','Harga','Diskon','TaxBase','OtherTaxBase','Tarif %','PPN'],desc=`DRAFT INTERNAL · NPWP penjual ${document.value.seller_tin} · NITKU ${document.value.seller_nitku} · Pembeli ${document.value.buyer_name}, ${document.value.buyer_address} · NPWP pembeli ${document.value.buyer_tin} · NITKU pembeli ${document.value.buyer_nitku} · Tanggal ${document.value.tax_date} · Kode ${document.value.trx_code} · ${dirty.value?'Belum disimpan':'Revisi '+revision.value} · Bukan faktur pajak yang telah disahkan DJP.`;if(kind==='excel')downloadFinanceXlsx('PTFAS_Pemeriksaan_Pajak.xlsx',[[desc],headings,...rows.value]);else writeFinancePrint(openFinancePrint(),'Pemeriksaan Draft Faktur Pajak',desc,headings,rows.value)}catch(e){error.value=financeError(e)}}
const exportHistory=kind=>{try{const rows=history.value.map(x=>[financeDate(x.changed_at),x.actor_name,x.after_data.revision,x.after_data.document?.seller_tin,x.after_data.document?.seller_nitku,x.after_data.document?.buyer_tin,x.after_data.document?.buyer_nitku,x.after_data.document?.tax_date,x.after_data.document?.trx_code,x.after_data.document?.notes]),headings=['Waktu','Petugas','Revisi','NPWP penjual','NITKU penjual','NPWP pembeli','NITKU pembeli','Tanggal pajak','Kode','Catatan'],title='Riwayat Draft Pajak — '+source.value.invoice_number;if(kind==='excel')downloadFinanceXlsx('PTFAS_Riwayat_Draft_Pajak.xlsx',[[title],['50 perubahan terakhir; status draft internal'],headings,...rows]);else writeFinancePrint(openFinancePrint(),title,'50 perubahan terakhir; status draft internal',headings,rows)}catch(e){error.value=financeError(e)}}
const showHistory=async()=>{try{history.value=(await getFinanceReportingHistory({kind:'TAX',reference:props.invoiceId})).data}catch(e){error.value=financeError(e)}}
onMounted(load)
</script>
<template>
 <div class="finance-ledger dialog-backdrop" @click.self="close"><section id="tax-draft-dialog" class="dialog coretax-editor" role="dialog" aria-modal="true" aria-labelledby="tax-draft-title"><header><div><h2 id="tax-draft-title">Persiapan Faktur Pajak · {{ source?.invoice_number||'Memuat…' }}</h2><small>Draft internal → XML → impor dan validasi di Coretax DJP</small></div><button :disabled="busy" @click="close">Tutup</button></header><div class="body"><p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="message" class="message" role="status">{{ message }}</p><p v-if="loading" role="status">Memuat data faktur dan draft…</p>
 <template v-if="document&&source"><p class="message">Subset ekspor: faktur normal domestik, pembeli NPWP/TIN, kode 01 atau 04, barang tanpa PPnBM. Retur, pengganti, uang muka, fasilitas, konsumen tanpa NPWP, dan ekspor luar negeri belum didukung otomatis.</p><p v-if="stale" class="message error">Faktur sumber telah berubah sejak draft disimpan. Periksa semua data, lalu simpan kembali sebelum ekspor XML.</p><form @submit.prevent="save"><fieldset :disabled="busy"><h3>Identitas perpajakan</h3><div class="form-grid"><label>NPWP penjual 16 digit<input v-model="document.seller_tin" maxlength="16" inputmode="numeric" /></label><label>NITKU penjual 22 digit<input v-model="document.seller_nitku" maxlength="22" inputmode="numeric" /></label><label>NPWP pembeli 16 digit<input v-model="document.buyer_tin" maxlength="16" inputmode="numeric" /></label><label>NITKU pembeli 22 digit<input v-model="document.buyer_nitku" maxlength="22" inputmode="numeric" /></label><label>Nama perpajakan pembeli<input v-model="document.buyer_name" maxlength="200" /></label><label>Email pembeli (opsional)<input v-model="document.buyer_email" type="email" maxlength="254" /></label><label class="span-two">Alamat perpajakan pembeli<textarea v-model="document.buyer_address" maxlength="1000" /></label><label>Tanggal faktur pajak<input v-model="document.tax_date" type="date" /></label><label>Kode transaksi<FasSelect v-model="document.trx_code" aria-label="Kode transaksi DJP"><option value="">Pilih setelah diperiksa Finance</option><option value="01">01 — normal sesuai perlakuan pajak</option><option value="04">04 — DPP nilai lain sesuai ketentuan</option></FasSelect></label></div>
 <h3>Rincian barang</h3><small>Kode barang dan satuan harus sesuai referensi DJP. Periksa harga sebelum PPN dan seluruh diskon, termasuk diskon faktur. Jangan memakai kode satuan internal BOX sebagai pengganti kode DJP.</small><div class="table-scroll coretax-lines"><table><thead><tr><th>Produk / Qty sumber</th><th v-for="[key,label] in columns" :key="key">{{ label }}</th></tr></thead><tbody><tr v-for="(item,index) in document.items" :key="item.source_id"><td><strong>{{ item.name }}</strong><small>Qty {{ item.qty }} · {{ source.items.find(x=>x.id===item.source_id)?.unit }}</small></td><td v-for="[key,label] in columns" :key="key"><input v-model="item[key]" :aria-label="label+' baris '+(index+1)" :maxlength="key==='code'?6:key==='unit'?7:19" :inputmode="['code','unit'].includes(key)?'text':'decimal'" :placeholder="key==='unit'?'UM.xxxx':''" /></td></tr></tbody></table></div><p class="muted">Total faktur sumber {{ money(source.total) }} · PPN sumber {{ money(source.vat) }}. TaxBase + PPN rincian wajib cocok dengan total sumber.</p><label class="tax-confirm"><input v-model="document.pkp_confirmed" type="checkbox" />Saya memastikan penjual berstatus PKP dan identitas, kode, satuan, DPP serta tarif telah diperiksa Finance.</label><label>Catatan pemeriksaan internal (opsional)<textarea v-model="document.notes" maxlength="2000" /></label>
 <section class="validation-panel"><h3>{{ checks.length?'Masih perlu dilengkapi':'Pemeriksaan lokal lolos' }}</h3><ul v-if="checks.length"><li v-for="item in checks" :key="item">{{ item }}</li></ul><p v-else>XML dapat disiapkan setelah draft disimpan. Validasi, penandatanganan, dan status resmi tetap diproses di Coretax DJP.</p></section>
 <div class="actions"><button class="primary" type="submit">{{ busy?'Memproses…':'Simpan draft' }}</button><button type="button" :disabled="!revision||dirty||stale||checks.length>0" @click="exportXML">Unduh XML Coretax</button><button type="button" @click="exportReview('excel')">Excel pemeriksaan</button><button type="button" @click="exportReview('print')">Print / PDF pemeriksaan</button><button type="button" @click="showHistory">Riwayat perubahan</button></div><small>Revisi {{ revision }} · {{ dirty?'Ada perubahan belum disimpan':'Isian tersimpan / belum ada draft baru' }}. Tidak ada pengiriman otomatis ke DJP.</small><p><a href="https://www.pajak.go.id/reformdjp/coretax/template-xml-dan-converter-excel-ke-xml" target="_blank" rel="noopener noreferrer">Template dan referensi resmi DJP</a> · <a href="https://coretaxdjp.pajak.go.id/" target="_blank" rel="noopener noreferrer">Buka Coretax DJP</a></p></fieldset></form>
 <div v-if="history.length"><h3>50 perubahan draft terakhir</h3><div class="actions"><button @click="exportHistory('excel')">Excel riwayat</button><button @click="exportHistory('print')">Print / PDF riwayat</button></div><div class="table-scroll"><table><thead><tr><th>Waktu</th><th>Petugas</th><th>Revisi</th><th>Catatan</th></tr></thead><tbody><tr v-for="item in history" :key="item.id"><td>{{ financeDate(item.changed_at) }}</td><td>{{ item.actor_name }}</td><td>{{ item.after_data.revision }}</td><td>{{ item.after_data.document?.notes }}</td></tr></tbody></table></div></div>
 </template></div></section></div>
</template>
<style scoped>
.coretax-editor{width:min(96vw,80rem)!important}.coretax-editor h3{font-size:.9rem;font-weight:750;margin:1.2rem 0 .8rem}.coretax-lines{margin:1rem 0}.coretax-lines table{min-width:1600px}.coretax-lines th,.coretax-lines td{padding:.6rem}.coretax-lines th:first-child,.coretax-lines td:first-child{position:sticky;left:0;z-index:1;background:var(--fas-elevated);box-shadow:1px 0 var(--fas-border)}.coretax-lines input{min-width:8rem}.coretax-lines td:first-child{min-width:14rem}.tax-confirm{display:flex!important;flex-direction:row!important;align-items:flex-start;gap:.7rem!important;margin:1rem 0}.tax-confirm input{width:1.15rem!important;min-height:1.15rem!important;height:1.15rem;flex-shrink:0;accent-color:var(--fas-accent)}.validation-panel{border:1px solid var(--fas-border);border-radius:.8rem;padding:.9rem;margin:1rem 0;background:var(--fas-overlay)}.validation-panel h3{margin:0 0 .6rem}.validation-panel ul{padding-left:1.2rem;list-style:disc}.validation-panel li{font-size:.78rem;line-height:1.7}.coretax-editor a{color:var(--fas-accent-text);text-decoration:underline}
</style>
